1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededException;
9	
10	/**
11	 * Rejects a create request once {@link #DAILY_LIMIT} or more owners have already been
12	 * registered today (by {@code registrationDate}). Runs before the owner is built, so the
13	 * count reflects the owners that already exist. Reported as a 429 by
14	 * {@link org.springframework.samples.petclinic.rest.escalation.DailyLimitExceededExceptionHandler}.
15	 */
16	public class RequireDailyLimit {
17	
18	    static final int DAILY_LIMIT = 100;
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DailyLimitExceededException {
22	        LocalDate today = LocalDate.now();
23	        long count = ownerRepository.findAll().stream()
24	            .filter(existing -> today.equals(existing.getRegistrationDate()))
25	            .count();
26	        if (count >= DAILY_LIMIT) {
27	            throw new DailyLimitExceededException(DAILY_LIMIT);
28	        }
29	    }
30	}
