3	/**
4	 * Thrown when a create request arrives after the maximum number of owners have already
5	 * been registered on the current day. Handled by
6	 * {@link DailyLimitExceededExceptionHandler}, which responds 429 Too Many Requests.
7	 */
8	public class DailyLimitExceededException extends Exception {
